#!/usr/bin/env bash
# Send the agent result to an IM webhook (generated by pi-cnb-cloud).
#
# Usage: notify.sh "<markdown text>"
# Webhook comes from AGENT_NOTIFY_WEBHOOK (put it in a CNB secret repo / imports).
# Supports WeCom, Feishu/Lark, DingTalk, Slack and any endpoint that accepts {"text": ...}.

set -uo pipefail

TEXT="${1:-}"
WEBHOOK="${AGENT_NOTIFY_WEBHOOK:-}"

[ -z "$WEBHOOK" ] && exit 0
[ -z "$TEXT" ] && TEXT="pi 云端 Agent 已结束"

case "$WEBHOOK" in
  *qyapi.weixin.qq.com*) KIND=wecom ;;
  *open.feishu.cn* | *open.larksuite.com* | *larksuite.com*) KIND=feishu ;;
  *oapi.dingtalk.com*) KIND=dingtalk ;;
  *hooks.slack.com*) KIND=slack ;;
  *) KIND=generic ;;
esac

PAYLOAD_FILE="${TMPDIR:-/tmp}/pi-cnb-agent-notify.json"
node -e '
  const [kind, text] = process.argv.slice(1);
  const title = text.split("\n").find((line) => line.trim()) || "pi cloud agent";
  let payload;
  switch (kind) {
    case "wecom":
      payload = { msgtype: "markdown", markdown: { content: text } };
      break;
    case "feishu":
      payload = { msg_type: "text", content: { text } };
      break;
    case "dingtalk":
      payload = { msgtype: "markdown", markdown: { title, text } };
      break;
    case "slack":
      payload = { text };
      break;
    default:
      payload = { text, title };
  }
  process.stdout.write(JSON.stringify(payload));
' "$KIND" "$TEXT" >"$PAYLOAD_FILE" || exit 1

curl -sS -m 15 -H 'Content-Type: application/json' -d @"$PAYLOAD_FILE" "$WEBHOOK" >/dev/null || exit 1
echo "✓ 通知已发送（$KIND）"